-- Resolve columns to flattened row slots, and validate before any execution.
import Json (..)
import Model (..)
import Data.List (..)
import Data.Foldable (all, any, length)

fn check(e : Expr, columns : List(Column), allow : Bool, inside : Bool) : Expr =
  if e.op == "col" then
    let matches = filter(
        \(c) -> c.name == e.name && (e.qualifier == "" || e.qualifier == c.qualifier),
        columns,
      )
    demand(length(matches) > 0, "UNKNOWN_COLUMN")
    demand(length(matches) == 1, "AMBIGUOUS_COLUMN")
    let c = at(matches, 0)
    Expr { ..e, index = c.index, source = c.source, kind = c.kind, nullable = c.nullable }
  elif e.op == "lit" then
    e
  else
    let isagg = agg(e.op)
    demand(not(isagg) || allow && not(inside), "INVALID_AGGREGATION")
    let args = map(\(a) -> check(a, columns, allow, inside || isagg), e.args)
    let ts = map(\(a) -> a.kind, args)
    let nuls = map(\(a) -> a.nullable, args)
    let kind_nul_result =
      if e.op == "IS_NULL" || e.op == "IS_NOT_NULL" then
        ("bool", false)
      elif e.op == "COUNT" then
        ("int", false)
      elif e.op == "COALESCE" then
        (at(ts, 0), false)
      elif elem(e.op, ["SUM", "+", "-", "*"]) then
        demand(all(\(t) -> t == "int" || t == "null", ts), "TYPE_ERROR")
        let has_non_null = any(\(t) -> t == "int", ts)
        ("int", not(has_non_null))
      elif elem(e.op, ["MIN", "MAX"]) then
        demand(length(args) > 0, "TYPE_ERROR")
        let non_null_ts = filter(\(t) -> t /= "null", ts)
        demand(length(non_null_ts) > 0 || all(\(n) -> n, nuls), "TYPE_ERROR")
        let base_type = if length(non_null_ts) > 0 then at(non_null_ts, 0) else at(ts, 0)
        demand(elem(base_type, ["int", "text", "null"]), "TYPE_ERROR")
        (base_type, any(\(n) -> n, nuls))
      elif elem(e.op, ["NOT", "AND", "OR"]) then
        demand(all(\(t) -> t == "bool" || t == "null", ts), "TYPE_ERROR")
        ("bool", e.op == "NOT" && at(nuls, 0) || e.op == "AND" && any(\(n) -> n, nuls) || e.op == "OR" && any(\(n) -> n, nuls))
      else
        demand(
            (at(ts, 0) == at(ts, 1) || at(ts, 0) == "null" || at(ts, 1) == "null")
              && (at(ts, 0) /= "bool" && at(ts, 1) /= "bool" || elem(e.op, ["=", "<>"])),
            "TYPE_ERROR",
          )
        let typ = if at(ts, 0) == "null" then at(ts, 1) else at(ts, 0)
        ("bool", at(nuls, 0) || at(nuls, 1))
    Expr { ..e, args = args, kind = fst(kind_nul_result), nullable = snd(kind_nul_result) }

fn predicate(e : Expr, columns : List(Column), allow : Bool) : Expr =
  let b = check(e, columns, allow, false)
  demand(b.kind == "bool", "TYPE_ERROR")
  b

pub fn tree_any(p : (Expr) -> Bool, e : Expr) : Bool =
  p(e) || any(\(a) -> tree_any(p, a), e.args)

fn grouped(e : Expr, keys : List(Int)) : Unit =
  if not(agg(e.op)) && e.op /= "IS_NULL" && e.op /= "IS_NOT_NULL" && e.op /= "COALESCE" then
    demand(e.op /= "col" || elem(e.index, keys), "INVALID_AGGREGATION")
    for a in sof(e.args) do
      grouped(a, keys)

fn find_table(database : List(Table), name : String) : Table =
  let ts = filter(\(t) -> t.name == name, database)
  demand(length(ts) > 0, "UNKNOWN_TABLE")
  at(ts, 0)

pub fn bind(q : Query, database : List(Table)) : Plan =
  let aliases = map(snd, q.select)
  demand(unique(aliases), "DUPLICATE_ALIAS")
  demand(unique(map(snd, q.sources)), "DUPLICATE_ALIAS")
  let tables = map(\(s) -> find_table(database, fst(s)), q.sources)
  var columns := []
  var joins := []
  for i in srange(0, length(tables)) do
    let t = at(tables, i)
    let offset = length(columns)
    let qualifier = snd(at(q.sources, i))
    let cs = map(
        \(k) -> Column { ..at(t.columns, k), index = offset + k, source = i, qualifier = qualifier },
        range(0, length(t.columns)),
      )
    columns := append(columns, cs)
    if i > 0 then
      let (on_expr, is_left) = at(q.joins, i - 1)
      joins := append(joins, [(predicate(on_expr, columns, false), is_left)])
  let cs = columns
  let sels = map(\(s) -> (check(fst(s), cs, true, false), snd(s)), q.select)
  let groups = map(\(e) -> check(e, cs, false, false), q.groups)
  let keys = map(\(e) -> e.index, groups)
  demand(unique(map(show_int, keys)), "INVALID_AGGREGATION")
  let pred = predicate(q.predicate, cs, false)
  let hav = predicate(q.having, cs, true)
  let roots = append(map(fst, sels), [hav])
  let aggregate =
    length(groups) > 0 || any(\(e) -> tree_any(\(n) -> agg(n.op), e), roots)
  demand(not(q.has_having) || aggregate, "INVALID_AGGREGATION")
  if aggregate then
    for e in sof(roots) do
      grouped(e, keys)
  let order_indices = []
  let bq =
    Query {
      ..q,
      select = sels,
      joins = joins,
      groups = groups,
      predicate = pred,
      having = hav
    }
  Plan {
    query = bq,
    tables = tables,
    filters = map(\(_) -> [], tables),
    aggregate = aggregate,
    order = []
  }

fn alias_index(names : List(String), n : String, i : Int) : Int =
  match names of
    Nil =>
      reject("UNKNOWN_COLUMN")
      -1
    Cons(a, rest) =>
      if a == n then
        i
      else
        alias_index(rest, n, i + 1)

-- Relational evaluation preserves input encounter order through every operator.
import Json (..)
import Model (..)
import Binder (tree_any)
import Data.List (..)
import Data.Foldable (all, length, sum)

pub fn compare_value(a : Json, b : Json) : Int =
  match (a, b) of
    (JInt(x), JInt(y)) => if x < y then -1 elif x > y then 1 else 0
    (JStr(x), JStr(y)) => str_cmp(x, y)
    (JBool(x), JBool(y)) => if x == y then 0 elif x then 1 else -1
    _ => 0

fn is_null(v : Json) : Bool =
  match v of
    JNull => true
    _ => false

pub fn evaluate(e : Expr, row : List(Json), group : List(List(Json))) : Json =
  let op = e.op
  if op == "lit" then
    e.value
  elif op == "col" then
    at(row, e.index)
  elif op == "IS_NULL" then
    JBool(is_null(evaluate(at(e.args, 0), row, group)))
  elif op == "IS_NOT_NULL" then
    JBool(not(is_null(evaluate(at(e.args, 0), row, group))))
  elif op == "COALESCE" then
    coalesce_eval(e.args, row, group)
  elif agg(op) then
    evaluate_agg(e, op, group)
  else
    evaluate_binary(e, row, group)

fn evaluate_agg(e : Expr, op : String, group : List(List(Json))) : Json =
  if op == "COUNT" then
    if length(e.args) == 0 then JInt(length(group)) else count_non_null(e.args, group)
  else
    let vals = map(\(r) -> evaluate(at(e.args, 0), r, []), group)
    let non_nulls = filter(\(v) -> not(is_null(v)), vals)
    if length(non_nulls) == 0 then JNull else eval_agg_non_null(op, non_nulls)

fn count_non_null(args : List(Expr), group : List(List(Json))) : Json =
  let non_nulls = filter(\(r) -> not(is_null(evaluate(at(args, 0), r, []))), group)
  JInt(length(non_nulls))

fn eval_agg_non_null(op : String, vals : List(Json)) : Json =
  if op == "SUM" then JInt(sum(map(integer, vals))) else extremum(vals, op == "MIN")

fn coalesce_eval(args : List(Expr), row : List(Json), group : List(List(Json))) : Json =
  match args of
    Nil => JNull
    Cons(e, rest) =>
      let v = evaluate(e, row, group)
      if is_null(v) then coalesce_eval(rest, row, group) else v

fn extremum(vs : List(Json), minimum : Bool) : Json =
  match vs of
    Nil => JNull
    Cons(v, Nil) => v
    Cons(v, rest) =>
      let b = extremum(rest, minimum)
      if (compare_value(v, b) < 0) == minimum then v else b

fn evaluate_binary(e : Expr, row : List(Json), group : List(List(Json))) : Json =
  let a = evaluate(at(e.args, 0), row, group)
  if e.op == "NOT" then
    evaluate_not(a)
  else
    let b = evaluate(at(e.args, 1), row, group)
    if e.op == "+" then evaluate_plus(a, b)
    elif e.op == "-" then evaluate_minus(a, b)
    elif e.op == "*" then evaluate_mult(a, b)
    elif e.op == "AND" then evaluate_and(a, b)
    elif e.op == "OR" then evaluate_or(a, b)
    else evaluate_comparison(e.op, a, b)

fn evaluate_not(a : Json) : Json =
  if is_null(a) then JNull else JBool(not(truth(a)))

fn evaluate_plus(a : Json, b : Json) : Json =
  if is_null(a) || is_null(b) then JNull else JInt(integer(a) + integer(b))

fn evaluate_minus(a : Json, b : Json) : Json =
  if is_null(a) || is_null(b) then JNull else JInt(integer(a) - integer(b))

fn evaluate_mult(a : Json, b : Json) : Json =
  if is_null(a) || is_null(b) then JNull else JInt(integer(a) * integer(b))

fn evaluate_and(a : Json, b : Json) : Json =
  if truth(a) == false then JBool(false)
  elif truth(b) == false then JBool(false)
  elif is_null(a) || is_null(b) then JNull
  else JBool(true)

fn evaluate_or(a : Json, b : Json) : Json =
  if truth(a) == true then JBool(true)
  elif truth(b) == true then JBool(true)
  elif is_null(a) || is_null(b) then JNull
  else JBool(false)

fn evaluate_comparison(op : String, a : Json, b : Json) : Json =
  if is_null(a) || is_null(b) then
    JNull
  else
    let c = compare_value(a, b)
    JBool(if op == "=" then c == 0 elif op == "<>" then c /= 0 elif op == "<" then c < 0 elif op == ">" then c > 0 elif op == "<=" then c <= 0 else c >= 0)

pub fn fold_constants(e : Expr) : Expr =
  let n = Expr { ..e, args = map(fold_constants, e.args) }
  if (not(agg(n.op)) && not(elem(n.op, ["lit", "col"])) && all(\(a) -> a.op == "lit", n.args)) then
    literal(evaluate(n, [], []))
  else
    n

fn conjuncts(e : Expr) : List(Expr) =
  if e.op == "AND" then append(conjuncts(at(e.args, 0)), conjuncts(at(e.args, 1))) else [e]

fn sources(e : Expr) : List(Int) =
  if e.op == "col" then [e.source] else flatten(map(sources, e.args))

fn combine(es : List(Expr)) : Expr =
  match es of
    Nil => literal(JBool(true))
    Cons(e, Nil) => e
    Cons(e, rest) => Expr { ..node("AND", [e, combine(rest)]), kind = "bool", nullable = false }

pub fn optimize(plan : Plan) : Plan =
  let q = plan.query
  let bq = Query { ..q, select = map(\(s) -> (fold_constants(fst(s)), snd(s)), q.select), joins = map(\((on, is_left)) -> (fold_constants(on), is_left), q.joins), having = fold_constants(q.having) }
  Plan { ..plan, query = bq }

fn join_rows_inner(left : List(List(Json)), right : List(List(Json)), on : Expr) : List(List(Json)) =
  flatten(map(\(l) -> filter(\(r) -> truth(evaluate(on, append(l, r), [])), map(\(r) -> append(l, r), right)), left))

fn join_rows_left(left : List(List(Json)), right : List(List(Json)), on : Expr, right_cols : Int) : List(List(Json)) =
  flatten(map(\(l) -> let matched = filter(\(r) -> truth(evaluate(on, append(l, r), [])), map(\(r) -> append(l, r), right)) in if length(matched) > 0 then matched else [append(l, replicate(right_cols, JNull))], left))

pub type Group = Group { key: String, rows: List(List(Json)) }

fn add_group(gs : List(Group), key : String, row : List(Json)) : List(Group) =
  match gs of
    Nil => [Group { key = key, rows = [row] }]
    Cons(g, rest) => if g.key == key then Cons(Group { ..g, rows = append(g.rows, [row]) }, rest) else Cons(g, add_group(rest, key, row))

fn groups_for(rows : List(List(Json)), keys : List(Expr)) : List(Group) =
  var gs := []
  for row in sof(rows) do
    let key = encode(JArr(map(\(e) -> evaluate(e, row, []), keys)))
    gs := add_group(gs, key, row)
  if length(keys) == 0 && length(rows) == 0 then [Group { key = "[]", rows = [] }] else gs

fn project(q : Query, row : List(Json), group : List(List(Json))) : List(List(Json)) =
  if truth(evaluate(q.having, row, group)) then [map(\(s) -> evaluate(fst(s), row, group), q.select)] else []

fn distinct_rows(rows : List(List(Json)), seen : List(String)) : List(List(Json)) =
  match rows of
    Nil => []
    Cons(r, rest) => let key = encode(JArr(r)) in if elem(key, seen) then distinct_rows(rest, seen) else Cons(r, distinct_rows(rest, Cons(key, seen)))

fn row_compare(a : List(Json), b : List(Json), order : List((Int, Bool, Int))) : Int =
  match order of
    Nil => 0
    Cons((i, desc, nulls_first), rest) =>
      let av = at(a, i)
      let bv = at(b, i)
      let a_null = is_null(av)
      let b_null = is_null(bv)
      if a_null /= b_null then
        let a_pos = if a_null then (if nulls_first > 0 then 0 else 1) else (if nulls_first > 0 then 1 else 0)
        let b_pos = if b_null then (if nulls_first > 0 then 0 else 1) else (if nulls_first > 0 then 1 else 0)
        if a_pos < b_pos then -1 else 1
      else if a_null && b_null then
        row_compare(a, b, rest)
      else
        let c = compare_value(av, bv)
        if c == 0 then row_compare(a, b, rest) elif desc then -c else c

fn insert_row(r : List(Json), rows : List(List(Json)), order : List((Int, Bool, Int))) : List(List(Json)) =
  match rows of
    Nil => [r]
    Cons(x, rest) => if row_compare(r, x, order) <= 0 then Cons(r, rows) else Cons(x, insert_row(r, rest, order))

fn sort_rows(rows : List(List(Json)), order : List((Int, Bool, Int))) : List(List(Json)) =
  match rows of
    Nil => []
    Cons(r, rest) => insert_row(r, sort_rows(rest, order), order)

pub fn execute(plan : Plan) : Json =
  let q = plan.query
  var scans := []
  var offset := 0
  for i in srange(0, length(plan.tables)) do
    let t = at(plan.tables, i)
    let rs = t.rows
    scans := append(scans, [rs])
    offset += length(t.columns)
  var rows := at(scans, 0)
  for i in srange(0, length(q.joins)) do
    let (on_expr, is_left) = at(q.joins, i)
    let right_table = at(plan.tables, i + 1)
    let right_cols = length(right_table.columns)
    rows := if is_left then join_rows_left(rows, at(scans, i + 1), on_expr, right_cols) else join_rows_inner(rows, at(scans, i + 1), on_expr)
  let filtered = filter(\(r) -> truth(evaluate(q.predicate, r, [])), rows)
  let projected = if plan.aggregate then flatten(map(\(g) -> project(q, if length(g.rows) > 0 then at(g.rows, 0) else [], g.rows), groups_for(filtered, q.groups))) else flatten(map(\(r) -> project(q, r, []), filtered))
  let distinct = if q.distinct then distinct_rows(projected, []) else projected
  let sorted = if length(plan.order) > 0 then sort_rows(distinct, plan.order) else distinct
  let skipped = drop(q.offset, sorted)
  let final = if q.limit >= 0 then take(q.limit, skipped) else skipped
  JObj([("columns", JArr(map(\(s) -> JStr(snd(s)), q.select))), ("rows", JArr(map(JArr, final)))])

-- The parser owns a scoped token-state effect; all ASTs are immutable values.
import Json (..)
import Data.String (..)
import Data.List (..)
import Data.Foldable (all, length)
import Model (..)
import Control.State (..)

pub type Token = Token { word: String, value: Json }

fn tok(s : String) : Token = Token { word = s, value = JNull }

fn scan_string(s : String, i : Int, acc : String) : (String, Int) =
  demand(i < byte_len(s), "PARSE_ERROR")
  if byte_at(s, i) == 39 then
    if i + 1 < byte_len(s) && byte_at(s, i + 1) == 39 then
      scan_string(s, i + 2, concat(acc, "'"))
    else
      (acc, i + 1)
  else
    scan_string(s, i + 1, concat(acc, str_of_char(chr(byte_at(s, i)))))

fn scan_word(s : String, i : Int, numbers : Bool) : Int =
  if i >= byte_len(s) then
    i
  else
    let c = byte_at(s, i)
    if (digit(c) || not(numbers) && (letter(c) || c >= 65 && c <= 90)) then
      scan_word(s, i + 1, numbers)
    else
      i

fn slice(s : String, i : Int, j : Int) : String =
  string_of_buf(slice_bytes(s, i, j, buf_empty()))

fn lex(s : String, i : Int) : List(Token) =
  if i >= byte_len(s) then
    [tok("$END")]
  else
    let c = byte_at(s, i)
    if elem(c, [32, 9, 10, 13]) then
      lex(s, i + 1)
    elif c == 39 then
      let (v, j) = scan_string(s, i + 1, "")
      Cons(Token { word = "LITERAL", value = JStr(v) }, lex(s, j))
    elif digit(c) then
      let j = scan_word(s, i, true)
      let n =
        match parse_int(slice(s, i, j)) of
          Some(v) => v
          None => 0
      Cons(Token { word = "NUMBER", value = JInt(n) }, lex(s, j))
    elif letter(c) || c >= 65 && c <= 90 then
      let j = scan_word(s, i, false)
      let w = slice(s, i, j)
      Cons(tok(if reserved(w) then to_upper(w) else w), lex(s, j))
    else
      let two = slice(s, i, min(i + 2, byte_len(s)))
      if elem(two, ["<>", "<=", ">="]) then
        Cons(tok(two), lex(s, i + 2))
      else
        demand(
            elem(c, [40, 41, 44, 46, 59, 43, 45, 42, 61, 60, 62]),
            "PARSE_ERROR",
          )
        Cons(tok(str_of_char(chr(c))), lex(s, i + 1))

fn peek() : String ! {State(List(Token))} = at(get(), 0).word

fn pop() : Token ! {State(List(Token)), Domain} =
  let ts = get()
  let t = at(ts, 0)
  demand(t.word /= "$END", "PARSE_ERROR")
  put(tail(ts))
  t

fn accept(w : String) : Bool ! {State(List(Token))} =
  if peek() == w then
    let ts = get()
    put(tail(ts))
    true
  else
    false

fn expect(w : String) : Unit = demand(accept(w), "PARSE_ERROR")

fn name() : String =
  let w = pop().word
  demand(name_ok(w), "PARSE_ERROR")
  w

fn natural() : Int =
  let t = pop()
  demand(t.word == "NUMBER", "PARSE_ERROR")
  integer(t.value)

fn reference() : Expr =
  let n = name()
  if accept(".") then
    column_ref(n, name())
  else
    column_ref("", n)

fn source() : (String, String) =
  let n = name()
  (n, if accept("AS") then name() else n)

fn precedence(op : String) : Int =
  if op == "OR" then
    1
  elif op == "AND" then
    2
  elif elem(op, ["=", "<>", "<", ">", "<=", ">="]) then
    4
  elif elem(op, ["+", "-"]) then
    5
  elif op == "*" then
    6
  else
    0

fn expression(minimum : Int) : Expr =
  let t = pop()
  let w = t.word
  let e =
    if w == "NOT" then
      node("NOT", [expression(3)])
    elif w == "IS" then
      reject("PARSE_ERROR")
      node("col", [])
    elif w == "NULL" then
      literal(JNull)
    elif w == "COALESCE" then
      expect("(")
      let args = coalesce_args()
      expect(")")
      node("COALESCE", args)
    elif w == "(" then
      let x = expression(1)
      expect(")")
      x
    elif w == "-" then
      literal(JInt(-natural()))
    elif elem(w, ["NUMBER", "LITERAL"]) then
      literal(t.value)
    elif elem(w, ["TRUE", "FALSE"]) then
      literal(JBool(w == "TRUE"))
    elif agg(w) then
      expect("(")
      let args =
        if w == "COUNT" && accept("*") then
          []
        else
          [expression(1)]
      expect(")")
      node(w, args)
    else
      demand(name_ok(w), "PARSE_ERROR")
      if accept(".") then
        column_ref(w, name())
      else
        column_ref("", w)
  binary(e, minimum, false)

fn coalesce_args() : List(Expr) ! {State(List(Token)), Domain} =
  let e = expression(1)
  demand(accept(","), "PARSE_ERROR")
  Cons(e, if peek() == ")" then [] else coalesce_args())

fn binary(left : Expr, minimum : Int, compared : Bool) : Expr =
  let op = peek()
  if op == "IS" then
    let ignored = pop()
    let not_flag = accept("NOT")
    expect("NULL")
    binary(node(if not_flag then "IS_NOT_NULL" else "IS_NULL", [left]), minimum, false)
  else
    let p = precedence(op)
    if p < minimum then
      left
    else
      demand(not(p == 4 && compared), "PARSE_ERROR")
      let ignored = pop()
      let right = expression(p + 1)
      binary(node(op, [left, right]), minimum, compared || p == 4)

fn selections() : List((Expr, String)) =
  let e = expression(1)
  expect("AS")
  let a = name()
  Cons((e, a), if accept(",") then selections() else [])

fn group_keys() : List(Expr) =
  let e = reference()
  Cons(e, if accept(",") then group_keys() else [])

fn order_keys() : List((String, Bool, Int)) =
  let n = name()
  let desc = accept("DESC")
  let ignored_asc = if desc then false else accept("ASC")
  let nulls_mode = if accept("NULLS") then
    if accept("FIRST") then 1 else if accept("LAST") then -1 else 0
  else
    if desc then 1 else -1
  Cons((n, desc, nulls_mode), if accept(",") then order_keys() else [])

fn join_sources(
  ss : List((String, String)),
  js : List((Expr, Bool))
) : (List((String, String)), List((Expr, Bool))) =
  if accept("LEFT") then
    let ignored = accept("OUTER")
    expect("JOIN")
    let s = source()
    expect("ON")
    let e = expression(1)
    join_sources(append(ss, [s]), append(js, [(e, true)]))
  elif elem(peek(), ["INNER", "JOIN"]) then
    let ignored = accept("INNER")
    expect("JOIN")
    let s = source()
    expect("ON")
    let e = expression(1)
    join_sources(append(ss, [s]), append(js, [(e, false)]))
  else
    (ss, js)

fn query() : Query =
  expect("SELECT")
  let distinct = accept("DISTINCT")
  let sels = selections()
  expect("FROM")
  let (ss, js) = join_sources([source()], [])
  let pred =
    if accept("WHERE") then
      expression(1)
    else
      literal(JBool(true))
  let groups =
    if accept("GROUP") then
      expect("BY")
      group_keys()
    else
      []
  let hh = accept("HAVING")
  let hav =
    if hh then
      expression(1)
    else
      literal(JBool(true))
  let order =
    if accept("ORDER") then
      expect("BY")
      order_keys()
    else
      []
  let lim =
    if accept("LIMIT") then
      natural()
    else
      -1
  let off =
    if lim >= 0 && accept("OFFSET") then
      natural()
    else
      0
  let ignored = accept(";")
  demand(peek() == "$END", "PARSE_ERROR")
  Query {
    select = sels,
    sources = ss,
    joins = js,
    predicate = pred,
    groups = groups,
    having = hav,
    has_having = hh,
    order = order,
